# Food Safety and Sanitation (cusafe): lessons. Facts only from the FDA Food Code 2022, FDA, USDA FSIS and their
# published handouts. Sanitizer strengths are never given as numbers. No first-aid content.
LESSONS = {
"hazards": LES([
 P("A food is unsafe when something in it can make a person sick or hurt. Kitchens sort those dangers into three kinds, because each is prevented a different way."),
 K("<b>Biological hazards:</b> bacteria, viruses and parasites, and the toxins some bacteria make. <b>Chemical hazards:</b> cleaning chemicals, pesticides, too much of an additive, and food allergens. <b>Physical hazards:</b> objects such as glass, metal shavings, bone, plastic or a bandage. Most foodborne illness comes from biological hazards."),
 TB(["Bacteria need", "So the kitchen…"], [
   ["Food (especially protein-rich, moist foods)", "treats meat, dairy, eggs, cooked rice, cut melons and cut leafy greens as foods that need time and temperature control"],
   ["Warmth", "keeps food out of the danger zone, 41°F to 135°F"],
   ["Time", "limits how long food stays warm"],
   ["Moisture", "knows dry foods (crackers, flour) are lower risk"],
   ["The right acidity and oxygen", "follows tested recipes for pickles and sealed foods"],
 ], "What bacteria need to grow"),
 W("Foods that support fast growth of germs are called <b>TCS foods</b> in the Food Code: foods that need Time and Temperature Control for Safety. Cooked rice, cut tomatoes and cut leafy greens are on that list, not just meat."),
 EX("Which kind?", "A chip of glass from a broken jar falls into a salad.", ["It is an object, not a germ or a chemical."], "A physical hazard. Throw the salad away."),
 M("Thinking you can smell or see unsafe food. The germs that cause most illness usually don't change the smell, look or taste of food. Spoilage germs do, but they are a different group."),
 DRILL("Look through your refrigerator and list the TCS foods: cooked leftovers, dairy, eggs, meat, cut fruit. These are the ones to watch for time and temperature."),
 SCI([("/biology/life-science/bacteria-growth/", "How bacteria multiply", "doubling, and why time matters"), ("/biology/life-science/helpful-harmful-microbes/", "Helpful and harmful microbes", "the germs in yogurt and the ones in food poisoning")]),
 MP([("guides/food-safety/", "Food Safety Basics", "clean, separate, cook and chill at home")]),
 TRY,
], "foodcode", "usda_dz"),

"danger-zone": LES([
 P("Bacteria multiply fastest at warm temperatures. Below about 41°F they slow down a lot; above about 135°F most stop growing. In between is the <b>temperature danger zone</b>."),
 K("<b>For restaurants</b>, the FDA Food Code says: hold cold TCS food at <b>41°F or below</b> and hot TCS food at <b>135°F or above</b>. <b>For home cooks</b>, USDA describes the danger zone as <b>40°F to 140°F</b> and says not to leave perishable food out more than <b>2 hours</b> (1 hour above 90°F)."),
 V("cu-cool", {"mode": "zone"}, "The danger zone on a thermometer: the Food Code's 41°F to 135°F, and USDA's 40°F to 140°F for home cooks."),
 W("Why two sets of numbers? They come from different documents written for different readers. The Food Code is a model code that state and local health departments adopt for restaurants and stores; USDA's numbers are a simple, cautious message for home kitchens. They agree on the point that matters: keep food out of the middle, and move it through quickly when cooking or cooling."),
 EX("In or out?", "A tray of cooked chicken on a buffet reads 128°F. Is it in the danger zone by the Food Code?", ["Hot holding must be 135°F or above.", "128°F is below that."], "Yes: it is in the danger zone and must be reheated or handled by the kitchen's rules."),
 M("Thinking the refrigerator makes food safe forever. Cold slows bacteria but does not kill them; that is why ready-to-eat food has a time limit even when cold."),
 DRILL("Put a thermometer in a glass of water in your refrigerator overnight. Is it at 40°F or below? Check the freezer is at 0°F."),
 MP([("kitchen/food-safety/#cold", "Fridge at 40°F, freezer at 0°F", "the home settings"), ("kitchen/food-safety/#two-hours", "The 2-hour rule", "leaving food out at home")]),
 TRY,
], "foodcode", "usda_dz", "g_dz"),

"cooking-temps": LES([
 P("Cooking kills germs when the food reaches a high enough temperature, held for long enough. The only reliable test is a thermometer in the thickest part of the food."),
 K("<b>USDA safe minimum internal temperatures (for consumers):</b> poultry, whole or ground, <b>165°F</b>; ground beef, pork, veal and lamb <b>160°F</b>; egg dishes <b>160°F</b>; beef, pork, veal and lamb steaks, chops and roasts <b>145°F</b> with a 3-minute rest; fish <b>145°F</b>; leftovers and casseroles <b>165°F</b>. <b>The Food Code (for restaurants)</b> pairs temperatures with times: for example 145°F for 15 seconds (whole cuts, fish, eggs cooked to order), 155°F for 17 seconds (ground meat), 165°F for under 1 second (poultry)."),
 TB(["Food", "USDA (home)", "Food Code (restaurants)"], [
   ["Chicken, turkey, duck (whole, parts, ground); stuffing", "165°F", "165°F, under 1 second"],
   ["Ground beef, pork, lamb", "160°F", "155°F for 17 seconds (or 158°F instantly, 150°F for 1 minute, 145°F for 3 minutes)"],
   ["Steaks, chops, roasts (beef, pork, veal, lamb)", "145°F + 3-minute rest", "145°F for 15 seconds; whole roasts by a time table"],
   ["Fish", "145°F, or opaque and flakes with a fork", "145°F for 15 seconds"],
   ["Eggs", "Cook until yolk and white are firm; egg dishes 160°F", "145°F for 15 seconds for an egg cooked to order"],
   ["Leftovers reheated", "165°F", "165°F for 15 seconds for hot holding"],
   ["Shrimp, lobster, crab, scallops", "Flesh pearly and opaque", "145°F for 15 seconds"],
   ["Clams, oysters, mussels", "Cook until shells open", "145°F for 15 seconds"],
 ], "Sources: USDA FSIS chart; FDA Food Code 3-401.11 as adopted by states"),
 V("cu-temps", None, "Test yourself: pick the USDA safe minimum temperature for each food."),
 W("Why is ground beef higher than a steak? On a whole steak, germs live on the surface, which gets very hot when seared. Grinding mixes the surface into the middle, so the center must get hot too. Poultry is highest because of germs such as Salmonella that can be all through it."),
 EX("Is it done?", "A chicken thigh reads 158°F in the thickest part, away from the bone.", ["Poultry must reach 165°F."], "Not yet: keep cooking and check again."),
 M("Checking the thin end or touching bone with the probe. Bone conducts heat differently. Put the tip in the center of the thickest part."),
 SAFE("Restaurants that serve food rarer than these temperatures (a rare burger, raw oysters, a soft egg) must tell customers in writing, by the Food Code's consumer advisory rule; some foods, such as undercooked ground meat, may not be served that way to highly susceptible groups."),
 DRILL("Cook a chicken breast and check it in three places. Write down all three readings and notice how much they differ."),
 MP([("guides/food-safety/#temperatures", "Safe minimum internal temperatures", "the USDA table, with notes"), ("kitchen/food-safety/#thermometer", "Using and checking a food thermometer", "where to put the probe")]),
 TRY,
], "usda_temps", "foodcode", "va_code"),

"cooling": LES([
 P("Hot food has to pass through the danger zone to get cold. The bigger the batch, the slower it cools, and a big pot in a refrigerator can stay warm in the middle for many hours."),
 K("<b>The Food Code's two-stage cooling rule:</b> cool cooked TCS food from <b>135°F to 70°F within 2 hours</b>, then from <b>70°F to 41°F or below within the next 4 hours</b>: 6 hours in all. The first stage is the strict one, because bacteria grow fastest between about 125°F and 70°F."),
 V("cu-cool", {"mode": "check"}, "Set when the food reached 70°F and 41°F, or try a cooling method, and see if it passes."),
 TB(["Method (Food Code 3-501.15)", "Why it works"], [
   ["Shallow pans (food about 2 inches deep or less), uncovered or loosely covered until cold", "More surface, less distance for heat to travel"],
   ["Cut large items into smaller pieces", "Thin pieces lose heat faster"],
   ["An ice-water bath, stirring often", "Water pulls heat far faster than air"],
   ["Ice wands (frozen paddles) stirred in", "Cool from the inside"],
   ["Ice added as an ingredient (for soups and stocks)", "The ice replaces some of the water in the recipe"],
   ["Blast chillers and tumble chillers", "Fast cold air or water made for cooling"],
 ], "Ways to cool faster"),
 W("If food reaches 70°F early, say in 1 hour, the FDA's handout says the remaining time still applies to reaching 41°F; the 6 hours in total is the outer limit. If food is not at 70°F within 2 hours, the Food Code says it must be reheated to 165°F and cooled again from the start, or thrown away, depending on the rules where you work."),
 EX("Did it pass?", "Chili is 135°F at noon, 72°F at 2:00 p.m., and 40°F at 5:00 p.m.", ["Stage 1: 135°F to 70°F must happen by 2:00 p.m. At 2:00 it was 72°F, still above 70°F.", "Stage 1 failed, even though stage 2 was fast."], "It did not pass."),
 EX("Time left", "Stock reaches 70°F 90 minutes after it was 135°F. By when must it reach 41°F, counting from 135°F?", ["6 hours in all from 135°F.", "It reached 70°F at 1.5 hours; the outer limit is 6 hours from the start."], "Within 6 hours of the start (4½ hours after it hit 70°F)."),
 M("Putting a lid on a deep, hot pot and putting it in the walk-in. The lid traps heat, the pot holds it, and warm air from it can warm nearby food."),
 DRILL("Make a pot of stock or soup. Split it: one half stays in the pot in the refrigerator; the other goes into a shallow pan set in an ice bath. Check both temperatures every 30 minutes for 2 hours and graph them."),
 SCI([("/math/differential-equations/growth-cooling/", "Newton's law of cooling", "why the cooling curve bends")]),
 TRY,
], "fda_cool", "foodcode"),

"holding-dating": LES([
 P("Food in a kitchen spends a lot of its life waiting: in the steam table, the walk-in, a prep container. The Food Code sets rules for each kind of waiting."),
 K("<b>Hot holding:</b> 135°F or above. <b>Cold holding:</b> 41°F or below. <b>Reheating for hot holding:</b> food cooked and cooled in the kitchen is reheated so all parts reach <b>165°F for 15 seconds</b>, within <b>2 hours</b>. <b>Date marking:</b> ready-to-eat TCS food kept more than 24 hours is labeled and used or thrown away within <b>7 days</b> at 41°F, counting the day it was made as day 1. <b>FIFO:</b> first in, first out."),
 LI("Label every container: what it is, the date made, and the use-by date (and your initials, in many kitchens).",
    "Put new deliveries behind or under older stock, so the older is used first.",
    "Check hot and cold holding temperatures on a schedule, and write them down.",
    "Steam tables and hot-holding cabinets are made to keep hot food hot, not to heat cold food; reheat on the range, in an oven or a microwave first."),
 W("Seven days is a limit for slow-growing germs such as Listeria, which can grow even in the cold. It is a safety limit, not a quality promise: many foods taste stale long before day 7."),
 EX("Use-by date", "Chicken salad is made on Monday, March 3. What is the last day to use it under the 7-day rule (made day counts as day 1)?", ["Day 1 is March 3. Day 7 is March 9."], "Sunday, March 9."),
 EX("Reheating", "Leftover soup from yesterday goes into the steam table at lunch. What must happen first?", ["Reheat so all of it reaches 165°F for 15 seconds, within 2 hours.", "Then hold at 135°F or above."], "Reheat to 165°F, then hold at 135°F or above."),
 M("Putting cold food straight into the steam table to \"warm up\". It spends far too long in the danger zone."),
 DRILL("Label everything in your refrigerator with masking tape: what it is and the date. After a week, see what you threw away and why."),
 MP([("kitchen/food-safety/#keeps", "How long it keeps", "leftovers and storage times at home"), ("guides/check-foods/#dates", "Dates on packages", "what \"use by\" and \"best if used by\" mean")]),
 TRY,
], "foodcode", "va_code"),

"cross-contamination": LES([
 P("Germs don't move on their own; we move them: on hands, boards, knives, towels, and drips from one food onto another."),
 K("<b>Separate raw from ready-to-eat.</b> Use separate boards and knives (or clean and sanitize between), wash hands after touching raw meat, and store food in the refrigerator <b>top to bottom by the temperature it must be cooked to</b>: ready-to-eat food at the top, then fish, then whole cuts of beef and pork, then ground meats, with raw poultry at the bottom."),
 V("cu-shelf", None, "Put the foods on the shelves in a safe order, top to bottom, then check."),
 W("The order works because anything that drips only drips onto food that will be cooked hotter. Chicken juice on the floor of the walk-in can't reach the salad above it; salad juice on chicken does no harm, because the chicken will be cooked to 165°F."),
 EX("Which shelf?", "Where do you store raw ground beef relative to raw salmon?", ["Ground beef must reach 155°F (Food Code) or 160°F (USDA); fish 145°F.", "The higher temperature goes lower."], "Ground beef below the salmon."),
 M("Using the same tongs for raw chicken going onto the grill and cooked chicken coming off. Use clean tongs, or wash them between."),
 DRILL("Rearrange your own refrigerator in the safe order. Put raw meat in a container or on a tray so it can't drip."),
 MP([("kitchen/cleaning/#boards", "Cutting boards and cross-contamination", "how to clean boards"), ("guides/food-safety/#four-steps", "Clean, separate, cook, chill", "the four habits")]),
 TRY,
], "foodcode", "usda_temps"),

"allergens": LES([
 P("For a person with a food allergy, a tiny amount of the wrong food can cause a serious reaction. Cooking does not destroy allergens, so the only protection is keeping them out of the food."),
 K("<b>The nine major food allergens</b> named by U.S. law (FDA): <b>milk, eggs, fish, crustacean shellfish, tree nuts, peanuts, wheat, soybeans</b> and <b>sesame</b>. Sesame was added by the FASTER Act, signed in 2021, and became a major allergen on <b>January 1, 2023</b>."),
 LI("Know every ingredient in every dish, including sauces, oils, garnishes and store-bought parts.",
    "When a guest says they have an allergy, tell the chef, and use clean tools, boards and pans.",
    "Fryer oil carries allergens: food fried in oil used for shrimp is not safe for a shellfish allergy.",
    "Picking an allergen off a finished plate does not make it safe; remake the dish.",
    "If you don't know, say you don't know and find out. Never guess."),
 W("Allergens are a chemical hazard in the Food Code's sense, and they are the one hazard heat can't fix. That is why menus and servers must be able to answer questions honestly."),
 EX("Safe or not?", "A guest is allergic to sesame. The burger bun has sesame seeds; the cook removes the bun and puts the patty on a plain bun.", ["Seeds and crumbs may already be on the patty.", "The safe fix is a new patty and bun prepared with clean tools."], "Not safe; start again with clean tools."),
 M("Thinking \"a little won't hurt\". For some people, a trace is enough."),
 DRILL("Read the labels in your pantry and find the \"Contains\" statement on five packages. Which of the nine allergens do you see most?"),
 MP([("guides/check-foods/#allergens", "The allergen statement", "reading labels at home")]),
 SCI([("/biology/high-school-biology/immune-system/", "The immune system", "what an allergic reaction is")]),
 TRY,
], "fda_allergen", "foodcode"),

"hygiene": LES([
 P("People are the most common way germs get into food. Good hygiene is the cheapest food safety there is."),
 K("<b>Wash hands for at least 20 seconds</b> with soap and warm water, scrubbing backs, between fingers and under nails, then dry with a single-use towel or air dryer. <b>Wash</b> before starting work, after the restroom, after handling raw meat, poultry or seafood, after touching your face, hair, phone, money or trash, after cleaning, and before putting on gloves. <b>Gloves</b> are for ready-to-eat food; change them when they tear, when you switch tasks, and after raw meat."),
 LI("Keep fingernails short and clean; cover cuts with a bandage and a glove.",
    "Hair restrained (hat or net); clean clothes and apron.",
    "No eating, drinking or smoking where food is prepared; a covered drink with a straw may be allowed away from food.",
    "Under the Food Code, workers with vomiting or diarrhea stay away from food work; illnesses such as norovirus spread easily through food."),
 W("Bare hands should not touch ready-to-eat food in a restaurant under the Food Code: use gloves, tongs or deli paper. Gloves stop germs only until they touch something dirty."),
 EX("Change gloves?", "You wore gloves to portion raw chicken. Now you need to plate a salad.", ["Raw chicken contaminated the gloves.", "Remove them, wash hands, then put on new gloves."], "Yes: take them off, wash your hands, new gloves."),
 M("Thinking gloves replace handwashing. Dirty hands make dirty gloves."),
 DRILL("Time your handwashing with a clock: 20 seconds is longer than it feels. Hum a short tune twice.", "Put a little cinnamon or flour on your hands, wash quickly, and look for what you missed."),
 TRY,
], "foodcode"),

"clean-sanitize": LES([
 P("A surface can look clean and still carry germs. That's why kitchens do two steps."),
 K("<b>Cleaning</b> removes food, grease and dirt with soap or detergent and water. <b>Sanitizing</b> reduces germs to a safe level, with heat or a chemical sanitizer, on a surface that is <b>already clean</b>. <b>Mix sanitizer exactly as its label says</b>, check its strength with the test strips made for it, and let it stay wet on the surface for the contact time on the label."),
 TB(["Three-compartment sink", "What happens"], [
   ["1. Wash", "Hot water and detergent; scrub off food"],
   ["2. Rinse", "Clean water removes detergent (soap can weaken some sanitizers)"],
   ["3. Sanitize", "Sanitizer at the label's strength and contact time, or hot water by the code's temperature"],
   ["Then air-dry", "Towels can put germs back"],
 ], "Washing dishes by hand in a commercial kitchen (scrape first)"),
 W("Food and grease shield germs from sanitizer, and some sanitizers are used up by food soil. Spraying sanitizer on a dirty board does little. Clean first, then sanitize."),
 EX("Order of steps", "A cutting board was used for raw chicken. What do you do before cutting lettuce on it?", ["Scrape and wash with detergent.", "Rinse.", "Sanitize as the label says and let it air-dry (or use a different, clean board)."], "Wash, rinse, sanitize, air-dry."),
 SAFE("Never mix cleaning chemicals; for example, bleach with ammonia or acids gives off harmful gases.", "Store chemicals below and away from food, in labeled containers.", "Read each chemical's safety data sheet and label; wear the gloves or eye protection they call for."),
 M("Drying sanitized dishes with a towel. Let them air-dry."),
 DRILL("Set up three basins at home (wash, rinse, sanitize) for one evening's dishes, using a sanitizer made for food-contact surfaces and following its label."),
 MP([("kitchen/cleaning/#clean-sanitize", "Cleaning vs. sanitizing", "the home version"), ("kitchen/cleaning/#bleach", "Using bleach safely", "what the label says")]),
 TRY,
], "foodcode"),

"haccp": LES([
 P("HACCP (say \"hassip\") is a way to plan food safety before anything goes wrong. It started with food for the U.S. space program in the 1960s and is now used by food plants and by restaurants for special processes."),
 K("<b>The seven principles:</b> (1) analyze hazards; (2) find the <b>critical control points</b> (CCPs), steps where control is essential, such as cooking and cooling; (3) set <b>critical limits</b> for each (for example, 165°F for poultry); (4) <b>monitor</b> them (who checks, how, how often); (5) set <b>corrective actions</b> when a limit is missed; (6) <b>verify</b> the plan works; (7) keep <b>records</b>."),
 TB(["Step for chicken soup", "CCP?", "Critical limit"], [
   ["Receiving raw chicken", "Often", "At 41°F or below"],
   ["Cooking the chicken", "Yes", "165°F"],
   ["Cooling the soup", "Yes", "135°F to 70°F in 2 hours; to 41°F within 6 hours in all"],
   ["Reheating for service", "Yes", "165°F for 15 seconds within 2 hours"],
   ["Chopping carrots", "Usually no", "(covered by basic hygiene)"],
 ], "A small HACCP table"),
 W("The Food Code requires a HACCP plan for some special processes in restaurants, such as reduced-oxygen packaging (vacuum-sealing and sous vide), curing, and smoking to preserve. Most daily cooking is covered by the code's ordinary rules instead."),
 EX("Corrective action", "The cooling log shows soup at 80°F two hours after it was 135°F.", ["Stage 1's limit (70°F within 2 hours) was missed.", "By the Food Code: reheat to 165°F and start cooling again, or discard; then find out why."], "Reheat to 165°F and cool again (or discard), and fix the cause."),
 M("Calling every step a critical control point. A CCP is where control is essential and the hazard can't be fixed later."),
 DRILL("Write a HACCP table for a dish you make, like chili or chicken salad: each step, whether it is a CCP, and its limit."),
 TRY,
], "foodcode", "w_haccp"),
}
